import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../providers/app_provider.dart';

class InventoryScreen extends ConsumerWidget { const InventoryScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final d = ref.watch(appProvider); return Scaffold(appBar: AppBar(title: const Text('Inventory')), floatingActionButton: FloatingActionButton.extended(onPressed: () => _add(context, ref), icon: const Icon(Icons.add), label: const Text('Product')), body: d.products.isEmpty ? const Center(child: Text('No products yet')) : ListView.builder(padding: const EdgeInsets.all(12), itemCount: d.products.length, itemBuilder: (_, i) { final p = d.products[i]; final low = p.stock <= p.minStock; return Card(child: ListTile(leading: CircleAvatar(child: Icon(low ? Icons.warning_amber : Icons.inventory_2_outlined)), title: Text(p.name), subtitle: Text('Stock ${p.stock.toStringAsFixed(0)} • Sell PKR ${p.sellingPrice.toStringAsFixed(0)}'), trailing: Text(low ? 'LOW' : p.stock.toStringAsFixed(0), style: TextStyle(fontWeight: FontWeight.bold, color: low ? Theme.of(context).colorScheme.error : null))); })); }
Future<void> _add(BuildContext context, WidgetRef ref) async { final name=TextEditingController(), buy=TextEditingController(), sell=TextEditingController(), stock=TextEditingController(), min=TextEditingController(); await showDialog(context: context, builder: (_) => AlertDialog(title: const Text('Add product'), content: SingleChildScrollView(child: Column(children: [TextField(controller: name, decoration: const InputDecoration(labelText: 'Product name')), TextField(controller: buy, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Purchase price')), TextField(controller: sell, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Selling price')), TextField(controller: stock, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Stock')), TextField(controller: min, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Minimum stock'))])), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: () { if (name.text.trim().isNotEmpty) { ref.read(appProvider.notifier).addProduct(name.text, double.tryParse(buy.text) ?? 0, double.tryParse(sell.text) ?? 0, double.tryParse(stock.text) ?? 0, double.tryParse(min.text) ?? 0); Navigator.pop(context); } }, child: const Text('Save'))])); }
}
